199	\begin{lemma}[Product form and Pauli relations of the pulled-apart observables]\label{lem:tildew-product-form}
200		\lean{MIPStarRE.QPBT.tildeObs_eq_heteroKron}
201		\lean{MIPStarRE.QPBT.tildeObs_isHermitian}
